function renderRoster(){
 const box=$('partyCharacters');box.replaceChildren();
 for(const c of PartyEngine.roster){const b=document.createElement('button');b.type='button';b.className='party-character';b.dataset.character=c.id;b.setAttribute('aria-label',c.name);b.setAttribute('aria-pressed',String(c.id===settings.character));b.style.setProperty('--character-color',typeof c.color==='number'?'#'+c.color.toString(16).padStart(6,'0'):c.color||'#83b7a0');
 const canvas=document.createElement('canvas');canvas.width=72;canvas.height=64;canvas.setAttribute('aria-hidden','true');const cx=canvas.getContext('2d');cx.imageSmoothingEnabled=false;if(window.Art?.drawCharacter)Art.drawCharacter(cx,c.id,36,61,{facing:1,frame:0,scale:.68});else{cx.fillStyle='#f7e7bd';cx.font='bold 18px sans-serif';cx.textAlign='center';cx.fillText(c.name.slice(0,2),36,37);}const label=document.createElement('small');label.textContent=c.name;b.append(canvas,label);b.addEventListener('click',()=>{settings.character=c.id;safeText('partyChosenName',c.name);box.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(preview?.players[0])preview.players[0].character=c.id;playNote(523,.08);});box.append(b);}
}
function renderCards(){const box=$('partyGameCards');box.replaceChildren();const themes={collapse:['MARCO','O chão não é seu amigo.','01'],race:['CARRO A GÁS','Curva boa se faz no limite.','02'],football:['MOTA','A quadra ficou pequena.','03'],spotlight:['NIKOLAS','O bolo vale esse risco?','04'],pages:['MENEZES','Passe no vão. Literalmente.','05'],waves:['REEEIS','O último de pé leva a resenha.','06'],harvest:['LUCAS','Equipe boa também sabe colher.','07'],sketch:['MARCO','UM CONTRA TODOS. Corre, turma!','08'],raft:['CARROÇA NÁUTICA','No mesmo barco. No mesmo ritmo.','09']};for(const game of PartyEngine.catalog){const meta=themes[game.id]||['A TURMA','Mais uma arena.','00'];const card=document.createElement('article');card.className='party-game-card';card.dataset.game=game.id;card.innerHTML='<div class="party-card-art" aria-hidden="true"><span class="party-card-number">'+meta[2]+'</span><div class="party-mini-scene"><i></i><i></i><i></i><i></i><b></b></div><span class="party-card-host">'+meta[0]+'</span></div><div class="party-card-copy"><h3></h3><p></p><button type="button">TREINAR ESTA ARENA ↗</button></div>';const format=document.createElement('span');format.className='party-format-tag';format.textContent=game.format==='solo'?'1 CONTRA A TURMA':game.format==='teams'?'EM EQUIPES':'TODOS CONTRA TODOS';card.querySelector('.party-card-copy').prepend(format);card.querySelector('h3').textContent=game.name;card.querySelector('p').textContent=meta[1];card.querySelector('button').addEventListener('click',()=>startOffline('practice',game.id));box.append(card);}}
function chooseMode(mode){settings.mode=mode;$('partyRounds').disabled=mode==='circuit';$('partyBoardMode').setAttribute('aria-pressed',String(mode==='board'));$('partyCircuitMode').setAttribute('aria-pressed',String(mode==='circuit'));safeText('partyModeHelp',mode==='board'?'Dados, bifurcações e armadilhas. Um minigame por rodada; 20 moedas compram uma estrela de açaí. Escolha rotas, visite lojas e desvie das armadilhas.':'As nove arenas em sequência, sem esperar o tabuleiro. Ganhe moedas nos minigames e dispute o melhor placar.');}
function previewWorld(){if(!window.PartyEngine)return null;return PartyEngine.create({players:fillPlayers([{id:'p0',name:settings.name,character:settings.character,bot:true}],4),rounds:3,mode:'board',seed:5035});}
function ensureArt(){if(art||renderFailure)return;try{qualityLow=false;slowFrames=0;art=PartyArt.create($('partyCanvas'),{onError:message=>failArt(message)});resize();}catch(e){failArt(e.message);}}
function failArt(message){renderFailure=String(message||'WebGL indisponível');if($('partyRenderError'))$('partyRenderError').hidden=false;}
function retryArt(){try{art?.dispose();}catch{}art=null;renderFailure='';$('partyRenderError').hidden=true;ensureArt();}
function resize(){if(!opened||!art)return;const r=overlay.getBoundingClientRect();art.resize(Math.max(1,r.width),Math.max(1,r.height),Math.min(1.5,devicePixelRatio||1));}
function open(){
 if(opened)return;if(!window.PartyEngine||!window.PartyArt){return;}
 init();const s=window.Game?.getState?.();resumeCampaign=!!(s?.started&&!s.paused&&!s.won&&!s.defeated);window.Game?.releaseInputs?.();if(resumeCampaign)Game.pause();opened=true;overlay.hidden=false;shell.classList.add('is-party');document.body.classList.add('party3d-open');view='lobby';setView('lobby');preview=previewWorld();ensureArt();resize();lastFrame=performance.now();accumulator=0;requestAnimationFrame(frame);$('partyCloseBtn').focus();
}
function requestClose(){if(world&&view==='live'&&world.phase!=='ceremony')showExit(true);else close(true);}
function showExit(on){confirmExit=on;$('partyExitConfirm').hidden=!on;if(on){resetInputs();safeText('partyExitDescription',role==='host'?'Você é o anfitrião. Sair encerra a sala de toda a turma.':'Você sairá da partida atual. O progresso da campanha está separado.');$('partyStayBtn').focus();}}
function close(force=false){if(!opened)return;if(!force&&world?.phase==='play'){showExit(true);return;}net?.close();net=null;lobby=null;world=null;preview=null;opened=false;resetInputs();stopAudio();overlay.hidden=true;confirmExit=false;$('partyExitConfirm').hidden=true;art?.dispose();art=null;renderFailure='';$('partyRenderError').hidden=true;shell.classList.remove('is-party');document.body.classList.remove('party3d-open');window.Game?.releaseInputs?.();if(resumeCampaign&&window.Game?.getState?.().started)Game.resume();resumeCampaign=false;entry.focus();}
function setView(next){view=next;overlay.dataset.view=next;$('partyLobby').hidden=next!=='lobby';$('partyNetworkPanel').hidden=next!=='network';$('partyLive').hidden=next!=='live';if(next!=='live'){for(const id of ['partyInstructions','partyResults','partyControls','partyShop','partyMapBtn'])$(id).hidden=true;}$('partyNetworkBadge').textContent=role==='offline'?'FESTA COM CPUs':role==='host'?'ANFITRIÃO · WI-FI':'TURMA · WI-FI';lastPhase='';lastUI=0;resetInputs();}
function fillPlayers(humans,seats){const players=humans.map(p=>({...p,bot:!!p.bot})),used=new Set(players.map(p=>p.character));let i=0;while(players.length<seats){const c=PartyEngine.roster.find(p=>!used.has(p.id))||PartyEngine.roster[i++%PartyEngine.roster.length];used.add(c.id);const ids=new Set(players.map(p=>p.id));const id=Array.from({length:8},(_,j)=>'p'+j).find(id=>!ids.has(id));players.push({id,name:c.name,character:c.id,bot:true});}return players.slice(0,8);}
function readSettings(){settings.name=$('partyName').value.trim().slice(0,18)||characterName(settings.character);settings.seats=clamp(Number($('partySeats').value)||4,4,8);settings.rounds=[3,5,8].includes(Number($('partyRounds').value))?Number($('partyRounds').value):3;return{...settings};}
function startOffline(mode,gameId){if(renderFailure)return;net?.close();net=null;lobby=null;role='offline';localId='p0';const s=readSettings();sessionConfig={...s,mode:mode||s.mode,gameId};world=PartyEngine.create({players:fillPlayers([{id:localId,name:s.name,character:s.character,bot:false}],s.seats),rounds:s.rounds,mode:mode||s.mode,gameId,seed:Math.floor(Math.random()*0x7fffffff)});setView('live');overview=false;art?.setOverview?.(false);resize();phaseUI();unlockAudio();playNote(659,.13);}
function openNetwork(){readSettings();setView('network');$('partyWifiGuide').hidden=isLan();$('partyWifiActions').hidden=!isLan();$('partyRoom').hidden=true;safeText('partyNetworkStatus',isLan()?'Cada amigo usa seu próprio aparelho. As vagas que sobrarem serão preenchidas por CPUs.':'Jogue agora com CPUs ou use o pacote Wi-Fi para reunir a turma.');}
function backFromNetwork(){net?.close();net=null;lobby=null;role='offline';setView('lobby');}
function createNet(){net?.close();net=PartyNet.create({onLobby:onLobby,onState:state=>{if(role==='guest'){world=state;if(view!=='live'){setView('live');overview=false;art?.setOverview?.(false);}}},onInput:(id,next)=>{if(role==='host'){remoteInputs[id]=next;remoteAt[id]=performance.now();}},onCommand:(id,cmd,value)=>{if(role==='host'&&world)PartyEngine.act(world,id,cmd,value);},onDisconnect:(id,info)=>{if(info?.hostLost){world=null;lobby=null;role='offline';setView('network');$('partyRoom').hidden=true;$('partyWifiActions').hidden=false;safeText('partyNetworkStatus',info.reason||'O anfitrião saiu. Criem outra sala.');return;}if(world&&role==='host'){PartyEngine.disconnect(world,id);delete remoteInputs[id];delete remoteAt[id];notice('Um amigo saiu. A CPU assumiu o lugar.');}},onError:text=>{safeText('partyNetworkStatus',text);notice(text);},onStatus:text=>safeText('partyNetworkStatus',text)});}
function createRoom(){if(!isLan())return;const s=readSettings();role='host';createNet();net.host({name:s.name,character:s.character,seats:s.seats,rounds:s.rounds,mode:s.mode});}
function joinRoom(){if(!isLan())return;const code=$('partyRoomInput').value.trim();if(!/^\d{6}$/.test(code)){safeText('partyNetworkStatus','O código tem seis números.');return;}const s=readSettings();role='guest';createNet();net.join({code,name:s.name,character:s.character});}
