function backToLobby(){net?.close();net=null;lobby=null;world=null;role='offline';preview=previewWorld();overview=true;art?.setOverview?.(true);setView('lobby');}
function command(cmd,value){if(!world)return;unlockAudio();if(role==='guest')net?.sendCommand(cmd,value);else PartyEngine.act(world,localId,cmd,value);}
