function renderShop(shop,yourTurn,p){const box=$('partyShop');box.hidden=!shop||!yourTurn;if(!shop||!yourTurn){lastShop='';return;}const key=world.round+':'+world.board.turn+':'+shop.type+':'+shop.node;if(lastShop!==key){lastShop=key;safeText('partyShopKicker',shop.type==='star'?'UMA ESTRELA DE AÇAÍ PRA CHAMAR DE SUA':'UMMHUMHUMM… A LOJA DO KAUA');safeText('partyShopTitle',shop.type==='star'?'VAI LEVAR A ESTRELA?':'ITENS PRA VIRAR A FESTA.');safeText('partyShopDescription',shop.type==='star'?'Ela custa 20 moedas. Depois da compra, a barraca muda de lugar.':'Você carrega até dois itens. Use B no começo do turno para ativar o primeiro.');const options=$('partyShopOptions');options.replaceChildren();const rows=shop.type==='star'?[{id:true,name:'COMPRAR ESTRELA',cost:20}]:shop.options;for(const item of rows){const btn=document.createElement('button');btn.type='button';btn.className='party-primary';btn.textContent=item.name+' · '+item.cost+' MOEDAS';btn.disabled=p.coins<item.cost||shop.type==='item'&&p.items.length>=2;btn.addEventListener('click',()=>command('buy',item.id));options.append(btn);}}safeText('partyShopClock',Math.ceil(Math.max(0,18-shop.time))+'s · SEU BOLSO: '+p.coins+' MOEDAS');}
