function moveStick(e){if(!stickCenter)return;let x=(e.clientX-stickCenter.x)/stickCenter.r,z=(e.clientY-stickCenter.z)/stickCenter.r;const length=Math.hypot(x,z);if(length>1){x/=length;z/=length;}stickX=Math.abs(x)<.12?0:x;stickZ=Math.abs(z)<.12?0:z;$('partyJoystick').style.setProperty('--stick-x',x*stickCenter.r+'px');$('partyJoystick').style.setProperty('--stick-y',z*stickCenter.r+'px');$('partyJoystick').setAttribute('aria-valuenow',String(Math.round(stickX*100)));}
