function unlockAudio(){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}}
function toggleSound(){soundOn=!soundOn;safeText('partySoundBtn','');$('partySoundBtn').innerHTML=svg('sound');$('partySoundBtn').setAttribute('aria-pressed',String(soundOn));$('partySoundBtn').setAttribute('aria-label',soundOn?'Desativar som':'Ativar som');if(soundOn){unlockAudio();musicAt=0;playNote(659,.12);}else stopAudio();}
function stopAudio(){if(audio){audio.suspend().catch(()=>{});}musicAt=0;}
function playNote(frequency,duration=.1,type='triangle',volume=.035){if(!soundOn||!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type=type;o.frequency.value=frequency;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+duration+.02);}catch{}}
